#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> modifiedMatrix(std::vector<std::vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        std::vector<int> col_max(n, -1);
        for (int c = 0; c < n; ++c) {
            for (int r = 0; r < m; ++r) {
                col_max[c] = std::max(col_max[c], matrix[r][c]);
            }
        }
        auto ans = matrix;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (ans[r][c] == -1) ans[r][c] = col_max[c];
            }
        }
        return ans;
    }
};

class Solution {
    public int[][] modifiedMatrix(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        int[] colMax = new int[n];
        for (int c = 0; c < n; ++c) {
            int mx = -1;
            for (int r = 0; r < m; ++r) mx = Math.max(mx, matrix[r][c]);
            colMax[c] = mx;
        }
        int[][] ans = new int[m][n];
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                ans[r][c] = matrix[r][c] == -1 ? colMax[c] : matrix[r][c];
            }
        }
        return ans;
    }
}

var modifiedMatrix = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    const colMax = new Array(n).fill(-1);
    for (let c = 0; c < n; ++c) {
        for (let r = 0; r < m; ++r) {
            colMax[c] = Math.max(colMax[c], matrix[r][c]);
        }
    }
    const ans = matrix.map(row => [...row]);
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            if (ans[r][c] === -1) ans[r][c] = colMax[c];
        }
    }
    return ans;
};
